// Format final response
const aiData = $('AI Response').item.json;
const contextData = $('Build Context').item.json;
const isVoiceInput = contextData.input_type === 'voice';

let aiResponse = 'Thank you for your message.';
if (aiData.message) {
  aiResponse = aiData.message;
} else if (aiData.content) {
  aiResponse = aiData.content;
} else if (aiData.choices && aiData.choices[0]) {
  aiResponse = aiData.choices[0].message.content;
}

let audioUrl = null;
if (isVoiceInput) {
  try {
    const ttsData = $('TTS Generation').first();
    if (ttsData && ttsData.binary && ttsData.binary.audio_response) {
      audioUrl = `data:audio/mp3;base64,${ttsData.binary.audio_response.data}`;
    }
  } catch (error) {
    console.warn('TTS failed:', error.message);
  }
}

// Generate appropriate CTA
let ctaMessage = '';
switch (contextData.intent) {
  case 'emergency':
    ctaMessage = '🚨 Call (970) 446-8995 immediately!';
    break;
  case 'estimation_request':
    ctaMessage = contextData.has_email ? 
      `📞 I'll send details to ${contextData.user_email}` :
      '📞 What email should I send the estimate to?';
    break;
  case 'scheduling':
    ctaMessage = '📅 Book at https://calendly.com/alpinepeakroofing/inspection';
    break;
  default:
    ctaMessage = contextData.has_email ? 
      'I\'ll send you more information!' :
      'What\'s your email for more details?';
}

return {
  json: {
    success: true,
    response: {
      message: aiResponse,
      audio_url: audioUrl,
      type: isVoiceInput ? 'voice' : 'text',
      timestamp: new Date().toISOString(),
      session_id: contextData.session_id,
      cta: ctaMessage
    },
    metadata: {
      input_type: contextData.input_type,
      intent: contextData.intent,
      priority: contextData.priority,
      lead_score: contextData.lead_score,
      email_captured: contextData.has_email,
      knowledge_used: contextData.has_knowledge
    }
  }
};

